INSERT INTO weenie (class_Id, class_Name, type, last_Modified) SELECT t.class_Id, t.class_Name, w.type, NOW() FROM acx_targets t JOIN weenie w ON w.class_Id = t.source;
INSERT INTO weenie_properties_int (object_Id, type, value) SELECT t.class_Id, p.type, p.value FROM acx_targets t JOIN weenie_properties_int p ON p.object_Id = t.source WHERE p.type NOT IN (67, 146, 332);   -- not Tolerance, XpOverride, LuminanceAward
INSERT INTO weenie_properties_int64 (object_Id, type, value) SELECT t.class_Id, p.type, p.value FROM acx_targets t JOIN weenie_properties_int64 p ON p.object_Id = t.source;
INSERT INTO weenie_properties_float (object_Id, type, value) SELECT t.class_Id, p.type, p.value FROM acx_targets t JOIN weenie_properties_float p ON p.object_Id = t.source;
INSERT INTO weenie_properties_bool (object_Id, type, value) SELECT t.class_Id, p.type, p.value FROM acx_targets t JOIN weenie_properties_bool p ON p.object_Id = t.source WHERE p.type NOT IN (29, 52);   -- not NoCorpse, AiImmobile
INSERT INTO weenie_properties_string (object_Id, type, value) SELECT t.class_Id, p.type, p.value FROM acx_targets t JOIN weenie_properties_string p ON p.object_Id = t.source WHERE p.type NOT IN (45, 49, 50);   -- not its kill quests
INSERT INTO weenie_properties_d_i_d (object_Id, type, value) SELECT t.class_Id, p.type, p.value FROM acx_targets t JOIN weenie_properties_d_i_d p ON p.object_Id = t.source WHERE p.type NOT IN (35, 61);   -- not its death treasure
INSERT INTO weenie_properties_i_i_d (object_Id, type, value) SELECT t.class_Id, p.type, p.value FROM acx_targets t JOIN weenie_properties_i_i_d p ON p.object_Id = t.source;
INSERT INTO weenie_properties_attribute (object_Id, type, init_Level, level_From_C_P, c_P_Spent) SELECT t.class_Id, p.type, p.init_Level, p.level_From_C_P, p.c_P_Spent FROM acx_targets t JOIN weenie_properties_attribute p ON p.object_Id = t.source;
INSERT INTO weenie_properties_attribute_2nd (object_Id, type, init_Level, level_From_C_P, c_P_Spent, current_Level) SELECT t.class_Id, p.type, p.init_Level, p.level_From_C_P, p.c_P_Spent, p.current_Level FROM acx_targets t JOIN weenie_properties_attribute_2nd p ON p.object_Id = t.source;
INSERT INTO weenie_properties_skill (object_Id, type, level_From_P_P, s_a_c, p_p, init_Level, resistance_At_Last_Check, last_Used_Time) SELECT t.class_Id, p.type, p.level_From_P_P, p.s_a_c, p.p_p, p.init_Level, p.resistance_At_Last_Check, p.last_Used_Time FROM acx_targets t JOIN weenie_properties_skill p ON p.object_Id = t.source;
INSERT INTO weenie_properties_body_part (object_Id, `key`, d_Type, d_Val, d_Var, base_Armor, armor_Vs_Slash, armor_Vs_Pierce, armor_Vs_Bludgeon, armor_Vs_Cold, armor_Vs_Fire, armor_Vs_Acid, armor_Vs_Electric, armor_Vs_Nether, b_h, h_l_f, m_l_f, l_l_f, h_r_f, m_r_f, l_r_f, h_l_b, m_l_b, l_l_b, h_r_b, m_r_b, l_r_b) SELECT t.class_Id, p.`key`, p.d_Type, p.d_Val, p.d_Var, p.base_Armor, p.armor_Vs_Slash, p.armor_Vs_Pierce, p.armor_Vs_Bludgeon, p.armor_Vs_Cold, p.armor_Vs_Fire, p.armor_Vs_Acid, p.armor_Vs_Electric, p.armor_Vs_Nether, p.b_h, p.h_l_f, p.m_l_f, p.l_l_f, p.h_r_f, p.m_r_f, p.l_r_f, p.h_l_b, p.m_l_b, p.l_l_b, p.h_r_b, p.m_r_b, p.l_r_b FROM acx_targets t JOIN weenie_properties_body_part p ON p.object_Id = t.source;
INSERT INTO weenie_properties_spell_book (object_Id, spell, probability) SELECT t.class_Id, p.spell, p.probability FROM acx_targets t JOIN weenie_properties_spell_book p ON p.object_Id = t.source;
INSERT INTO weenie_properties_create_list (object_Id, destination_Type, weenie_Class_Id, stack_Size, palette, shade, try_To_Bond) SELECT t.class_Id, p.destination_Type, p.weenie_Class_Id, p.stack_Size, p.palette, p.shade, p.try_To_Bond FROM acx_targets t JOIN weenie_properties_create_list p ON p.object_Id = t.source WHERE p.destination_Type IN (2, 10);   -- what it wields, for its looks; no loot
INSERT INTO weenie_properties_palette (object_Id, sub_Palette_Id, offset, length) SELECT t.class_Id, p.sub_Palette_Id, p.offset, p.length FROM acx_targets t JOIN weenie_properties_palette p ON p.object_Id = t.source;
INSERT INTO weenie_properties_texture_map (object_Id, `index`, old_Id, new_Id) SELECT t.class_Id, p.`index`, p.old_Id, p.new_Id FROM acx_targets t JOIN weenie_properties_texture_map p ON p.object_Id = t.source;
INSERT INTO weenie_properties_anim_part (object_Id, `index`, animation_Id) SELECT t.class_Id, p.`index`, p.animation_Id FROM acx_targets t JOIN weenie_properties_anim_part p ON p.object_Id = t.source;
INSERT INTO weenie_properties_event_filter (object_Id, event) SELECT t.class_Id, p.event FROM acx_targets t JOIN weenie_properties_event_filter p ON p.object_Id = t.source;
INSERT INTO weenie_properties_int (object_Id, type, value) SELECT class_Id, 67, 1 FROM acx_targets;   -- Tolerance: NoAttack, never fights back
