INSERT INTO weenie_properties_bool (object_Id, type, value) SELECT class_Id, 29, 1 FROM acx_targets;   -- NoCorpse
INSERT INTO weenie_properties_bool (object_Id, type, value) SELECT class_Id, 30013, 1 FROM acx_targets;   -- AcxPracticeTarget
