-- Project ACX (2026-11-14): Concordia's target range, the cave room around 0x018A02F1 [50.5 -71.2 6] (JJ: "the other room
-- I want to turn into a shooting range so to speak. Is it possible to spawn certain mobs and make them docile? so players
-- can see what their weapons will do to them?", "one of each type of popular monster. Olthoi, tusker, tumerok, undead,
-- golem, I basically want one to represent all the weaknesses ... a 10 second respawn time ... one around the level 50
-- range and one in the 180 range. They keep their melee D and defenses"; "It doesnt even have to be popular"; "maybe select
-- monsters with smaller frames. i.e. undead weak to fire stomper weak to fire": no tuskers).
-- Eighteen practice targets: copies of real monsters with the same level, attributes, skills (defenses too), health,
-- body armor, resistances and looks, that never attack (Tolerance NoAttack), never move (AiImmobile), leave no corpse
-- or loot, and carry AcxPracticeTarget (bool 30013), so their death pays no experience or luminance and counts for no
-- kill task, contract, invasion, T.A.R. camp or /xph (Creature_Death.cs). No emotes, no kill quests.
-- A U along the walls, facing in, with the middle and both doorways clear (JJ: "you still have lots of wall space to use.
-- you can move one row to the other side then you have the west wall too"): the level-180 set (Olthoi, Tumerok, Undead, Golem, Banderling, Sclavus, Skeleton) from
-- the north-east corner along the north wall and down the top of the west wall, the level-50 set in the same order from
-- the south-east along the south wall and up the bottom of the west wall, so each type's two levels face each other.
-- The north wall starts east of the north-west corridor's landing; the south wall stops short of the south-east exit.
-- JJ then nudged them back against the walls, partly up the slopes (positions below are JJ's, from Preview's DB).
-- The east wall (JJ: "we have a empty wall ... We could add a large lugian and a tusker?"), north to south: Tukora
-- Sentinel 185 and Stomper 185, then Tusker Liberator 60 and Extas Lugian 80 (no regular Lugian spawns near 50).
-- Every damage type is the weakness of one target or more in each set; nether is nobody's (nearly all take it at 1.0).
-- A retail 10-second linkable generator (28282) respawns each 10 s after it dies.
-- Generated by ~/Work/ac/tools/target_range.py from the DAT's flat floor. Weenies 900790-900808 (900808 the hall marker), guids
-- 0x7018AB80-0x7018AB9F. Re-runnable.
DELETE FROM weenie WHERE class_Id BETWEEN 900790 AND 900808;
DROP TEMPORARY TABLE IF EXISTS acx_targets;
CREATE TEMPORARY TABLE acx_targets (class_Id INT UNSIGNED PRIMARY KEY, source INT UNSIGNED, class_Name VARCHAR(100));
DROP TEMPORARY TABLE acx_targets;
-- the hall marker: a baby Stomper named for what is down the hall, that can't be attacked
UPDATE weenie_properties_string SET value = 'Target Range' WHERE object_Id = 900808 AND type = 1;
DELETE FROM weenie_properties_float WHERE object_Id = 900808 AND type = 39;
DELETE FROM weenie_properties_bool WHERE object_Id = 900808 AND type = 19;
-- the marker keeps the Stomper's emotes (JJ: "can it keep the emotes?"): idle motions on its heartbeat. Each copied set
-- carries its source set's id in quest while its actions are copied, then quest goes back to empty.
SELECT 900808, category, probability, weenie_Class_Id, style, substyle, CONCAT('acx-src-', id), vendor_Type, min_Health, max_Health FROM weenie_properties_emote WHERE object_Id = 31313;
SELECT n.id, a.`order`, a.type, a.delay, a.extent, a.motion, a.message, a.test_String, a.min, a.max, a.min_64, a.max_64, a.min_Dbl, a.max_Dbl, a.stat, a.display, a.amount, a.amount_64, a.hero_X_P_64, a.percent, a.spell_Id, a.wealth_Rating, a.treasure_Class, a.treasure_Type, a.p_Script, a.sound, a.destination_Type, a.weenie_Class_Id, a.stack_Size, a.palette, a.shade, a.try_To_Bond, a.obj_Cell_Id, a.origin_X, a.origin_Y, a.origin_Z, a.angles_W, a.angles_X, a.angles_Y, a.angles_Z
FROM weenie_properties_emote n JOIN weenie_properties_emote_action a ON a.emote_Id = CAST(SUBSTRING(n.quest, 9) AS UNSIGNED) WHERE n.object_Id = 900808 AND n.quest LIKE 'acx-src-%';
UPDATE weenie_properties_emote SET quest = NULL WHERE object_Id = 900808 AND quest LIKE 'acx-src-%';

DELETE FROM landblock_instance_link WHERE parent_GUID BETWEEN 0x7018AB80 AND 0x7018AB9F;
DELETE FROM landblock_instance WHERE guid BETWEEN 0x7018AB80 AND 0x7018AB9F;
